# Environment secrets pulled from Bitwarden on every machine.
#
#   ENV_VAR_NAME        bitwarden-item-name        [field, default: password]
#
# Values never appear in this repo, in logs, or on the command line -- only the
# item name lives here. Store the value in the vault, then re-run the setup.

DEEPSEEK_API_KEY      deepseek-api-key

# ANTHROPIC_API_KEY     anthropic-api-key
# OPENAI_API_KEY        openai-api-key
